const fs = require('fs');
const cachePath = '/data/cache_pendientes.json';
const productos = [];

for (const item of $input.all()) {
    const data = item.json;

    const rawCat = data['CATEGORÍA'] || '';
    const cat = rawCat ? rawCat.charAt(0).toUpperCase() + rawCat.slice(1).toLowerCase() : 'SinCategoria';
    const name = data['NOMBRE'] || '';

    const basePath = `/data/your-photos-folder/${cat}/${name}`;
    const extensions = ['.jpg', '.png', '.jpeg', '.JPG', '.PNG'];

    let imageBase64 = null;
    let finalPath = null;

    for (const ext of extensions) {
        if (fs.existsSync(basePath + ext)) {
            finalPath = basePath + ext;
            break;
        }
    }

    try {
        if (finalPath) {
            const ext = finalPath.split('.').pop().toLowerCase();
            const mime = (ext === 'png') ? 'image/png' : 'image/jpeg';
            const buffer = fs.readFileSync(finalPath);
            imageBase64 = `data:${mime};base64,${buffer.toString('base64')}`;
        }
    } catch (err) {
        console.error('Error leyendo imagen:', err.message);
    }

    const usd = data['PRECIO USD NUEVO'] ? `$${data['PRECIO USD NUEVO']} USD` : '';
    const cup = data['PRECIO CUP NUEVO'] ? `${data['PRECIO CUP NUEVO']} CUP` : '';
    const precioFinal = [cup, usd].filter(Boolean).join(' | ');

    productos.push({
        id_unico: data['CÓDIGO'],
        nombre: name,
        precio: precioFinal,
        estado: data['ESTADO PUBLICACIÓN'] || 'NO PUBLICADO',
        imagen: imageBase64
    });
}

fs.writeFileSync(cachePath, JSON.stringify(productos));

return [{ json: { status: 'success', total_cacheados: productos.length } }];

const fs = require('fs');
let productos = [];

try {
    const rawData = fs.readFileSync('/data/cache_pendientes.json', 'utf8');
    productos = JSON.parse(rawData);
} catch (e) {
    productos = [];
}

// Escapamos los datos para inyectarlos de forma 100% segura en JS
const safeProductosJson = JSON.stringify(productos).replace(/</g, '\\u003c');

let cardsHtml = '';
for (const prod of productos) {
    const imgSrc = prod.imagen ? prod.imagen : 'https://via.placeholder.com/400x400?text=Sin+Imagen';
    const colorBorde = prod.estado === 'PENDIENTE ACTUALIZAR' ? '#e74c3c' : '#6d1e68';

    // El botón AHORA SOLO RECIBE EL ID. Cero errores de sintaxis.
    cardsHtml += `
    <div class="card" id="card-${prod.id_unico}" style="border-left: 6px solid ${colorBorde};">
        <img src="${imgSrc}" loading="lazy" alt="Producto" />
        <div class="card-content">
            <h3>${prod.nombre}</h3>
            <p class="price">${prod.precio}</p>
            <p class="badge">${prod.estado}</p>
            <button onclick="prepararPublicacion('${prod.id_unico}')">
                Preparar y Publicar
            </button>
        </div>
    </div>`;
}

